"""
FilmPulse - Movie Review Sentiment Analytics
TF-IDF + Multinomial Naive Bayes, presented as a Streamlit dashboard.

Run with:   streamlit run filmpulse.py

Project mode (this folder):  filmpulse.py + filmpulse_model.joblib + filmpulse_movies.csv + filmpulse_reviews.csv
Standalone mode:             the build script embeds the model, movies and sample reviews into this
                             file (see the _PAYLOAD block at the very bottom). New reviews are then
                             saved to filmpulse_user_reviews.csv, created next to the script.
"""
from __future__ import annotations

import base64
import csv
import hashlib
import html
import io
import json
import os
import re
import threading
import warnings
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd
import plotly.graph_objects as go
import streamlit as st

# ======================================================================================
# PAGE CONFIG  (must be the first Streamlit call)
# ======================================================================================
st.set_page_config(
    page_title="FilmPulse | Movie Sentiment Analytics",
    page_icon="🎬",
    layout="wide",
    initial_sidebar_state="expanded",
)

# ======================================================================================
# CONSTANTS
# ======================================================================================
BASE_DIR = Path(__file__).resolve().parent
MODEL_PATH = BASE_DIR / "filmpulse_model.joblib"
MOVIES_PATH = BASE_DIR / "filmpulse_movies.csv"
PROJECT_REVIEWS_PATH = BASE_DIR / "filmpulse_reviews.csv"      # project mode: seed + new reviews
STANDALONE_REVIEWS_PATH = BASE_DIR / "filmpulse_user_reviews.csv"  # standalone mode: new reviews only

MOVIE_COLUMNS = ["movie_id", "title", "genre", "year", "poster", "description"]
REVIEW_COLUMNS = ["movie_id", "username", "review", "review_type", "sentiment"]
STORE_COLUMNS = REVIEW_COLUMNS + ["submitted_at"]
MIN_REVIEWS = 5          # minimum reviews before a movie gets a sentiment verdict
TAGLINE = "Where every opinion shapes a movie's reputation."

# Palette
BG, BG2, CARD = "#090A10", "#11131C", "#171A26"
CRIMSON, VIOLET, BLUE, GOLD = "#E6395B", "#8B5CF6", "#3B82F6", "#D6B36A"
TEXT, MUTED = "#F5F5FA", "#A1A1B5"
POS_COLOR, NEG_COLOR = BLUE, CRIMSON          # one consistent meaning for sentiment colours
SENTIMENTS = ("Positive", "Negative")
FONT = "Inter, 'Segoe UI', system-ui, sans-serif"
DISPLAY = "Sora, Inter, 'Segoe UI', system-ui, sans-serif"

# Original evaluation of the already-trained model on the IMDb test set.
# These are the project's recorded results; they are NOT recomputed from the demo reviews.
CONFUSION = np.array([[11091, 1409], [1781, 10719]])   # rows = actual [Neg, Pos], cols = predicted

