def esc(value) -> str:
    """HTML-escape any value. All user-provided text is escaped before it is displayed."""
    return html.escape("" if value is None else str(value), quote=True)


# ======================================================================================
# STORAGE LAYER (CSV, append-only with a lock; works in project and standalone mode)
# ======================================================================================
class StoreError(RuntimeError):
    """The reviews file exists but cannot be used (wrong columns, unreadable, ...)."""


class DuplicateReview(Exception):
    """The same user already submitted this exact review for this movie."""


def payload() -> dict | None:
    """Embedded data (standalone mode) or None (project mode, files next to the script)."""
    return globals().get("_PAYLOAD")


def reviews_store_path() -> Path:
    return STANDALONE_REVIEWS_PATH if payload() is not None else PROJECT_REVIEWS_PATH


def file_stamp(path: Path) -> tuple[int, int]:
    """(mtime, size) of a file - changes whenever the file changes - or (0, 0) if it is absent."""
    try:
        info = path.stat()
    except FileNotFoundError:
        return (0, 0)
    return info.st_mtime_ns, info.st_size


@st.cache_resource(show_spinner=False)
def store_lock() -> threading.RLock:
    """One lock shared by every browser session of this server process."""
    return threading.RLock()


def _read_csv_text(source) -> pd.DataFrame:
    try:
        return pd.read_csv(source, encoding="utf-8-sig") if isinstance(source, Path) else pd.read_csv(io.StringIO(source))
    except pd.errors.EmptyDataError:
        return pd.DataFrame()


def _ensure_store(path: Path) -> None:
    """Create the reviews file, or upgrade it in place to include the submitted_at column."""
    if not path.exists() or path.stat().st_size == 0:
        with open(path, "w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerow(STORE_COLUMNS)
        return
    with open(path, newline="", encoding="utf-8-sig") as fh:
        rows = list(csv.reader(fh))
    header = rows[0]
    missing = [c for c in REVIEW_COLUMNS if c not in header]
    if missing:
        raise StoreError(f"{path.name} is missing required columns: {', '.join(missing)}")
    if "submitted_at" in header:
        return
    tmp = path.with_name(path.name + ".tmp")
    with open(tmp, "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh)
        w.writerow(header + ["submitted_at"])
        w.writerows(r + [""] for r in rows[1:] if r)
    os.replace(tmp, path)


def _clean_reviews(df: pd.DataFrame, valid_ids: tuple) -> tuple[pd.DataFrame, int]:
    """Normalise a raw reviews table. Returns (clean rows, number of rows ignored as invalid)."""
    if df.empty:
        return pd.DataFrame(columns=STORE_COLUMNS), 0
    missing = [c for c in REVIEW_COLUMNS if c not in df.columns]
    if missing:
        raise StoreError(f"The reviews data is missing columns: {', '.join(missing)}")
    if "submitted_at" not in df.columns:
        df = df.assign(submitted_at="")
    df = df[STORE_COLUMNS].copy()
    before = len(df)
    df["movie_id"] = pd.to_numeric(df["movie_id"], errors="coerce")
    df["sentiment"] = df["sentiment"].astype(str).str.strip().str.title()
    df["review"] = df["review"].fillna("").astype(str).str.strip()
    df["username"] = df["username"].fillna("Anonymous").astype(str).str.strip()
    df["review_type"] = df["review_type"].fillna("Sample").astype(str).str.strip()
    df["submitted_at"] = pd.to_datetime(df["submitted_at"], errors="coerce", utc=True)
    df = df.dropna(subset=["movie_id"])
    df["movie_id"] = df["movie_id"].astype(int)
    df = df[df["movie_id"].isin(valid_ids) & df["sentiment"].isin(SENTIMENTS) & (df["review"] != "")]
    return df.reset_index(drop=True), before - len(df)


def read_all_reviews(valid_ids: tuple) -> tuple[pd.DataFrame, int]:
    """Seed reviews (embedded or project file) plus the user store, uncached."""
    frames, dropped = [], 0
    data = payload()
    if data is not None:
        seed, d = _clean_reviews(_read_csv_text(data["reviews_csv"]), valid_ids)
        frames.append(seed)
        dropped += d
    path = reviews_store_path()
    if path.exists() and path.stat().st_size > 0:
        extra, d = _clean_reviews(_read_csv_text(path), valid_ids)
        frames.append(extra)
        dropped += d
    frames = [f for f in frames if not f.empty]
    if not frames:
        return pd.DataFrame(columns=STORE_COLUMNS), dropped
    return pd.concat(frames, ignore_index=True), dropped


def append_review(movie_id: int, username: str, review: str, sentiment: str, valid_ids: tuple) -> None:
    """Append one review. Raises DuplicateReview / StoreError / OSError. Thread-safe."""
    with store_lock():
        current, _ = read_all_reviews(valid_ids)          # fresh read: guards against stale caches and races
        if not current.empty:
            same = current[(current["movie_id"] == movie_id)
                           & (current["username"].str.lower() == username.lower())
                           & (current["review"].str.lower() == review.lower())]
            if not same.empty:
                raise DuplicateReview()
        path = reviews_store_path()
        _ensure_store(path)
        with open(path, "rb") as fh:                       # make sure the file ends with a newline
            size = fh.seek(0, os.SEEK_END)
            if size > 0:
                fh.seek(size - 1)
                needs_newline = fh.read(1) not in (b"\n", b"\r")
            else:
                needs_newline = False
        with open(path, "a", newline="", encoding="utf-8") as fh:
            if needs_newline:
                fh.write("\n")
            csv.writer(fh).writerow([int(movie_id), username, review, "User", sentiment,
                                     datetime.now(timezone.utc).isoformat(timespec="seconds")])
    load_reviews.clear()           # drop cached copies right away (they are also keyed by file stamp)
    get_stats.clear()


# ======================================================================================
# CACHED DATA LOADERS
# ======================================================================================
@st.cache_data(show_spinner=False)
def load_movies(stamp: tuple) -> pd.DataFrame:
    data = payload()
    df = _read_csv_text(data["movies_csv"]) if data is not None else _read_csv_text(MOVIES_PATH)
    missing = [c for c in MOVIE_COLUMNS if c not in df.columns]
    if missing:
        raise ValueError(f"The movie catalogue is missing columns: {', '.join(missing)}")
    df = df[MOVIE_COLUMNS].copy()
    df["movie_id"] = pd.to_numeric(df["movie_id"], errors="coerce")
    df = df.dropna(subset=["movie_id"]).drop_duplicates("movie_id")
    df["movie_id"] = df["movie_id"].astype(int)
    df["year"] = pd.to_numeric(df["year"], errors="coerce").fillna(0).astype(int)
    for col in ("title", "genre", "poster", "description"):
        df[col] = df[col].fillna("").astype(str).str.strip()
    df["genre_list"] = df["genre"].apply(lambda g: [x.strip() for x in g.split(",") if x.strip()])
    return df.reset_index(drop=True)


@st.cache_data(show_spinner=False)
def load_reviews(stamp: tuple, valid_ids: tuple) -> tuple[pd.DataFrame, int]:
    return read_all_reviews(valid_ids)


def verdict_for(pos: int, neg: int) -> str:
    total = pos + neg
    if total < MIN_REVIEWS:
        return "Not Enough Reviews Yet"
    if pos * 2 > total:
        return "Positive"
    if pos * 2 < total:
        return "Negative"
    return "Mixed"


VERDICT_CLASS = {"Positive": "pos", "Negative": "neg", "Mixed": "mixed", "Not Enough Reviews Yet": "low"}


@st.cache_data(show_spinner=False)
def get_stats(version: tuple, _movies: pd.DataFrame, _reviews: pd.DataFrame) -> pd.DataFrame:
    """One row per movie: counts, percentages, verdict. Cached per data version (files' stamps)."""
    if _reviews.empty:
        counts = pd.DataFrame(columns=list(SENTIMENTS))
    else:
        counts = _reviews.groupby(["movie_id", "sentiment"]).size().unstack(fill_value=0)
    for col in SENTIMENTS:
        if col not in counts.columns:
            counts[col] = 0
    stats = _movies.merge(counts[list(SENTIMENTS)].rename(columns={"Positive": "positive", "Negative": "negative"}),
                          left_on="movie_id", right_index=True, how="left")
    stats[["positive", "negative"]] = stats[["positive", "negative"]].fillna(0).astype(int)
    stats["total"] = stats["positive"] + stats["negative"]
    safe_total = stats["total"].replace(0, np.nan)
    stats["pos_pct"] = (stats["positive"] / safe_total * 100).fillna(0.0)
    stats["neg_pct"] = (stats["negative"] / safe_total * 100).fillna(0.0)
    stats["verdict"] = [verdict_for(p, n) for p, n in zip(stats["positive"], stats["negative"])]
    return stats


CTX: dict = {}


def build_context() -> dict:
    """Load (cached) movies, reviews and per-movie statistics once per script run."""
    data = payload()
    movies_stamp = ("embedded",) if data is not None else file_stamp(MOVIES_PATH)
    if data is None and movies_stamp == (0, 0):
        raise FileNotFoundError(f"filmpulse_movies.csv was not found next to filmpulse.py ({BASE_DIR}).")
    movies = load_movies(movies_stamp)
    store_stamp = file_stamp(reviews_store_path())
    valid_ids = tuple(movies["movie_id"])
    reviews, dropped = load_reviews(store_stamp, valid_ids)
    version = (movies_stamp, store_stamp)
    stats = get_stats(version, movies, reviews)
    return dict(movies=movies, reviews=reviews, stats=stats, dropped=dropped, valid_ids=valid_ids, version=version)


# ======================================================================================
# MODEL LAYER
# ======================================================================================
def to_label(cls) -> str:
    """Map the model's class value to a sentiment label (the saved model uses 0 / 1)."""
    key = str(cls).strip().lower()
    if key in {"1", "positive", "pos", "true"}:
        return "Positive"
    if key in {"0", "negative", "neg", "false"}:
        return "Negative"
    raise ValueError(f"Unrecognised model class: {cls!r}")


def _rebuild_embedded_model(data: dict):
    """Re-create the trained TF-IDF vectorizer and Naive Bayes model from the embedded arrays.

    Every learned parameter (vocabulary, IDF weights, log-probabilities, priors, counts) is restored
    exactly as saved - nothing is retrained. This avoids pickle, so it works on any scikit-learn version.
    """
    from sklearn.feature_extraction.text import TfidfVectorizer
    from sklearn.naive_bayes import MultinomialNB

    raw = base64.b64decode("".join(data["model_b64"].split()))
    if hashlib.sha256(raw).hexdigest() != data["model_sha256"]:
        raise ValueError("The embedded model data is corrupted (checksum mismatch). Re-copy filmpulse.py without editing it.")
    arrays = np.load(io.BytesIO(raw), allow_pickle=False)
    meta = data["model_meta"]
    terms = bytes(arrays["vocab"]).decode("utf-8").split("\n")
    vocabulary = {t: i for i, t in enumerate(terms)}
    params = dict(meta["vectorizer_params"])
    params["ngram_range"] = tuple(params["ngram_range"])
    vectorizer = TfidfVectorizer(vocabulary=vocabulary, **params)
    vectorizer.idf_ = arrays["idf"]
    model = MultinomialNB(alpha=meta["alpha"])
    model.classes_ = arrays["classes"]
    model.class_count_ = arrays["class_count"]
    model.class_log_prior_ = arrays["class_log_prior"]
    model.feature_count_ = arrays["feature_count"]
    model.feature_log_prob_ = arrays["feature_log_prob"]
    model.n_features_in_ = int(arrays["feature_log_prob"].shape[1])
    return model, vectorizer


@st.cache_resource(show_spinner=False)
def load_model_bundle(source: str):
    """Load the trained model + vectorizer once per server process. Returns (model, vectorizer, notes)."""
    data = payload()
    if data is not None:
        model, vectorizer = _rebuild_embedded_model(data)
        return model, vectorizer, ["Loaded from the model parameters embedded in this file (no pickle, no retraining)."]
    import joblib
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        bundle = joblib.load(MODEL_PATH)
    notes = [str(w.message).split("\n")[0] for w in caught]
    return bundle["model"], bundle["vectorizer"], notes


def get_model():
    if payload() is None and not MODEL_PATH.exists():
        raise FileNotFoundError(f"filmpulse_model.joblib was not found next to filmpulse.py ({BASE_DIR}).")
    return load_model_bundle("embedded" if payload() is not None else str(MODEL_PATH))


def classify(text: str, model, vectorizer) -> tuple[str, float, float]:
    """TF-IDF transform + Naive Bayes prediction. Returns (label, confidence, P(positive))."""
    features = vectorizer.transform([text])
    if features.nnz == 0:
        raise ValueError("none of the words in this review are known to the model")
    proba = model.predict_proba(features)[0]
    labels = [to_label(c) for c in model.classes_]
    p_pos = float(proba[labels.index("Positive")])
    idx = int(np.argmax(proba))
    return labels[idx], float(proba[idx]), p_pos


@st.cache_data(show_spinner=False)
def model_top_terms(_model, _vectorizer, n: int = 10):
    """Words/phrases the model links most strongly to each class (from its learned probabilities)."""
    names = np.array(_vectorizer.get_feature_names_out())
    classes = [to_label(c) for c in _model.classes_]
    diff = _model.feature_log_prob_[classes.index("Positive")] - _model.feature_log_prob_[classes.index("Negative")]
    freq = _model.feature_count_.sum(axis=0)
    diff = np.where(freq >= np.percentile(freq, 90), diff, 0.0)      # ignore rare terms
    order = np.argsort(diff)
    return ([(names[i], float(diff[i])) for i in order[::-1][:n]], [(names[i], float(-diff[i])) for i in order[:n]])


# ======================================================================================
# HTML BUILDING BLOCKS
# ======================================================================================
def md(html_str: str) -> None:
    st.markdown(html_str, unsafe_allow_html=True)


def page_header(eyebrow: str, title: str, subtitle: str) -> None:
    md(f'<div class="fp-pagehead"><div class="fp-eyebrow">{esc(eyebrow)}</div><div class="fp-pagetitle">{esc(title)}</div>'
       f'<div class="fp-pagesub">{esc(subtitle)}</div></div>')


def section(title: str, sub: str = "") -> None:
    sub_html = f'<div class="fp-h3sub">{esc(sub)}</div>' if sub else '<div style="height:.7rem"></div>'
    md(f'<div class="fp-h3">{esc(title)}</div>{sub_html}')


def note(text: str, kind: str = "") -> None:
    md(f'<div class="fp-note {kind}">{text}</div>')


def alert(text: str, kind: str = "") -> str:
    return f'<div class="fp-alert {kind}" role="alert">{esc(text)}</div>'


def counter(value: float, suffix: str = "", decimals: int = 0) -> str:
    """Animated number: counts up in CSS (no JavaScript); the final value is always correct."""
    text = f"{value:.{decimals}f}"
    whole, _, frac = text.partition(".")
    tail = (f".{frac}" if frac else "") + suffix
    return (f'<span class="fp-sr">{esc(text + suffix)}</span><span aria-hidden="true">'
            f'<span class="fp-count" style="--n:{int(whole)}"></span>{esc(tail)}</span>')


def kpi(label: str, value_html: str, sub: str = "", icon: str = "film", color: str = VIOLET, delay: float = 0) -> str:
    return (f'<div class="fp-kpi" style="--ac:{color};--accent:{color};--d:{delay}s"><div class="fp-kpi-ic">{ICONS[icon]}</div>'
            f'<div class="fp-kpi-l">{esc(label)}</div><div class="fp-kpi-v">{value_html}</div><div class="fp-kpi-s">{esc(sub)}</div></div>')


def kpi_row(cards: list[str]) -> None:
    for col, c in zip(st.columns(len(cards), gap="medium"), cards):
        col.markdown(c, unsafe_allow_html=True)


def pill(verdict: str) -> str:
    return f'<span class="fp-pill {VERDICT_CLASS.get(verdict, "low")}">{esc(verdict)}</span>'


def poster_html(row, badge: str = "") -> str:
    """Poster with a styled placeholder underneath. If the image is missing or fails to load, the placeholder
    simply stays visible - a broken poster never shows an error."""
    url = str(row["poster"]).strip()
    hue = 330 + (int(row["movie_id"]) * 47) % 70           # crimson-to-blue family
    img = ""
    if url.lower().startswith(("http://", "https://")) and not re.search(r"[\s'\"()<>]", url):
        img = f'<img src="{esc(url)}" alt="{esc(row["title"])}" loading="lazy" decoding="async" referrerpolicy="no-referrer">'
    return (f'<div class="fp-poster" style="--h:{hue % 360}"><div class="fp-ph">{FILM_ICON}<span class="fp-ph-t">{esc(row["title"])}</span>'
            f'<span class="fp-ph-y">{esc(row["year"])}</span></div>{img}{badge}</div>')


def badge_html(row) -> str:
    if row["verdict"] == "Not Enough Reviews Yet":
        return '<span class="fp-badge">Not enough reviews</span>'
    pct = row["neg_pct"] if row["verdict"] == "Negative" else row["pos_pct"]
    return f'<span class="fp-badge {VERDICT_CLASS[row["verdict"]]}">{esc(row["verdict"])} · {pct:.0f}%</span>'


def sentiment_bar(row) -> str:
    return (f'<div class="fp-bar"><span class="pos" style="width:{row["pos_pct"]:.1f}%"></span>'
            f'<span class="neg" style="width:{row["neg_pct"]:.1f}%"></span></div>'
            f'<div class="fp-counts"><span><b>{row["positive"]}</b> positive</span>'
            f'<span><b>{row["negative"]}</b> negative</span></div>')


def movie_card(row, compact: bool = False, delay: float = 0) -> str:
    chips = "".join(f'<span class="fp-chip">{esc(g)}</span>' for g in row["genre_list"])
    year = f'<span class="fp-chip year">{esc(row["year"])}</span>'
    desc = "" if compact else f'<div class="fp-desc">{esc(row["description"])}</div>'
    meta = "" if compact else f'<div class="fp-meta">{year}{chips}</div>'
    return (f'<div class="fp-card" style="--d:{delay}s">{poster_html(row, badge_html(row))}<div class="fp-body">'
            f'<div class="fp-title">{esc(row["title"])}</div>{meta}{desc}{sentiment_bar(row)}</div></div>')


def review_card(row, movie_title: str = "", delay: float = 0) -> str:
    name = row["username"] or "Anonymous"
    new = '<span class="fp-new">NEW</span>' if row["review_type"] == "User" else ""
    movie = f'<div class="fp-rev-movie">on <b>{esc(movie_title)}</b></div>' if movie_title else ""
    return (f'<div class="fp-rev" style="--d:{delay}s"><div class="fp-rev-top"><span class="fp-user">'
            f'<span class="fp-avatar">{esc(name[:1].upper())}</span>{esc(name)}{new}</span>'
            f'{pill(row["sentiment"])}</div>{movie}<div class="fp-rev-text">{esc(row["review"])}</div></div>')


def html_table(df: pd.DataFrame, sep_rows: tuple = ()) -> str:
    head = "".join(f"<th>{esc(c)}</th>" for c in df.columns)
    body = ""
    for i, (_, r) in enumerate(df.iterrows()):
        cls = ' class="sep"' if i in sep_rows else ""
        body += f"<tr{cls}>" + "".join(f"<td>{esc(v)}</td>" for v in r) + "</tr>"
    return f'<table class="fp-table"><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>'


def box(title: str, body: str, icon: str = "", delay: float = 0) -> str:
    ic = f"<i>{icon}</i>" if icon else ""
    return f'<div class="fp-box" style="--d:{delay}s"><div class="fp-box-t">{ic}{esc(title)}</div><div class="fp-box-x">{body}</div></div>'


# ======================================================================================
# CHARTS
# ======================================================================================
def style_fig(fig: go.Figure, title: str, height: int = 340) -> go.Figure:
    fig.update_layout(
        title=dict(text=title, x=0, xanchor="left", font=dict(family=DISPLAY, size=15, color=TEXT)),
        height=height, margin=dict(l=8, r=8, t=54, b=10),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family=FONT, color=TEXT, size=12),
        hoverlabel=dict(bgcolor="#1b1e2e", bordercolor="rgba(255,255,255,.18)", font=dict(family=FONT, color=TEXT)),
        legend=dict(orientation="h", yanchor="bottom", y=1.0, xanchor="right", x=1, font=dict(color=MUTED)),
        transition=dict(duration=450, easing="cubic-in-out"),
    )
    fig.update_xaxes(gridcolor="rgba(255,255,255,.06)", zerolinecolor="rgba(255,255,255,.06)", linecolor="rgba(255,255,255,.1)", tickfont=dict(color=MUTED))
    fig.update_yaxes(gridcolor="rgba(255,255,255,.06)", zerolinecolor="rgba(255,255,255,.06)", linecolor="rgba(255,255,255,.1)", tickfont=dict(color=MUTED))
    return fig


_card_ids = iter(range(10_000))


def card():
    """A styled glass surface (keyed container; styled through the st-key-fpcard CSS class)."""
    return st.container(key=f"fpcard_{next(_card_ids)}")


def show_chart(fig: go.Figure) -> None:
    with card():
        st.plotly_chart(fig, width="stretch", config={"displayModeBar": False})


def donut(pos: int, neg: int, title: str) -> go.Figure:
    fig = go.Figure(go.Pie(
        labels=list(SENTIMENTS), values=[pos, neg], hole=0.68, sort=False, direction="clockwise",
        marker=dict(colors=[POS_COLOR, NEG_COLOR], line=dict(color=CARD, width=3)),
        textinfo="percent", textposition="inside", insidetextorientation="horizontal",
        textfont=dict(color="#FFFFFF", size=13, family=FONT),
        hovertemplate="%{label}: %{value} reviews (%{percent})<extra></extra>"))
    fig.add_annotation(text=f"<b>{pos + neg:,}</b><br><span style='font-size:11px;color:{MUTED}'>reviews</span>",
                       showarrow=False, font=dict(size=26, family=DISPLAY, color=TEXT))
    style_fig(fig, title, 330)
    fig.update_layout(legend=dict(orientation="h", y=-0.02, x=0.5, xanchor="center", yanchor="top"))
    return fig


def pct_bar(df: pd.DataFrame, col: str, color: str, title: str, label: str) -> go.Figure:
    df = df.iloc[::-1]
    fig = go.Figure(go.Bar(
        x=df[col], y=df["title"], orientation="h", marker=dict(color=color, line=dict(width=0)),
        text=[f"{v:.0f}%" for v in df[col]], textposition="inside", insidetextanchor="end",
        textfont=dict(color="#fff", family=FONT, size=12),
        customdata=np.stack([df["positive"], df["negative"], df["total"]], axis=-1),
        hovertemplate=("<b>%{y}</b><br>" + label + ": %{x:.0f}%<br>"
                       "%{customdata[0]} positive, %{customdata[1]} negative (%{customdata[2]} reviews)<extra></extra>")))
    style_fig(fig, title, max(260, 50 * len(df) + 90))
    fig.update_xaxes(range=[0, 100], ticksuffix="%")
    return fig


def stacked_by_movie(stats: pd.DataFrame) -> go.Figure:
    df = stats[stats["total"] > 0].sort_values(["pos_pct", "total"], ascending=[True, True])
    fig = go.Figure()
    for name, col, color in (("Positive", "pos_pct", POS_COLOR), ("Negative", "neg_pct", NEG_COLOR)):
        fig.add_trace(go.Bar(
            name=name, x=df[col], y=df["title"], orientation="h", marker=dict(color=color),
            customdata=df[["positive", "negative", "total"]].to_numpy(),
            hovertemplate="<b>%{y}</b><br>" + name + ": %{x:.0f}% of %{customdata[2]} reviews<extra></extra>"))
    style_fig(fig, "Sentiment by movie", max(420, 26 * len(df) + 90))
    fig.update_layout(barmode="stack")
    fig.update_xaxes(range=[0, 100], ticksuffix="%")
    return fig


def stacked_counts(df: pd.DataFrame, x: str, title: str, height: int = 360, horizontal: bool = False) -> go.Figure:
    fig = go.Figure()
    for name, col, color in (("Positive", "positive", POS_COLOR), ("Negative", "negative", NEG_COLOR)):
        kw = dict(x=df[col], y=df[x], orientation="h") if horizontal else dict(x=df[x], y=df[col])
        fig.add_trace(go.Bar(name=name, marker=dict(color=color), hovertemplate="<b>%{" + ("y" if horizontal else "x") + "}</b><br>"
                             + name + ": %{" + ("x" if horizontal else "y") + "}<extra></extra>", **kw))
    style_fig(fig, title, height).update_layout(barmode="stack")
    return fig


