def page_home() -> None:
    movies, reviews, stats = CTX["movies"], CTX["reviews"], CTX["stats"]
    total = len(reviews)
    pos = int((reviews["sentiment"] == "Positive").sum())
    neg = total - pos
    user_n = int((reviews["review_type"] == "User").sum())
    md('<div class="fp-hero"><svg class="fp-hero-pulse" viewBox="0 0 430 120" fill="none"><defs><linearGradient id="hp" x1="0" x2="1"><stop offset="0" stop-color="#E6395B"/>'
       '<stop offset="1" stop-color="#3B82F6"/></linearGradient></defs><path d="M0 70H120L140 70L160 22L190 104L214 46L232 70H430" stroke="url(#hp)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'
       '<span class="fp-hero-badge">★ Movie sentiment analytics</span>'
       '<div class="fp-hero-title">Film<b>Pulse</b></div>'
       f'<div class="fp-hero-tag">{esc(TAGLINE)}</div>'
       '<div class="fp-hero-text">Browse the catalogue, read what audiences are saying and add your own review. Every review is classified as '
       'Positive or Negative by a TF-IDF + Naive Bayes model, and the whole dashboard updates immediately.</div></div>')

    if total == 0:
        kpi_row([kpi("Movies analysed", counter(len(movies)), "in the catalogue", "film", VIOLET)])
        md('<div class="fp-empty" style="margin-top:1.4rem">No reviews yet. Open <b>Write a Review</b> to add the first one.</div>')
        return

    pos_pct, neg_pct = pos / total * 100, neg / total * 100
    kpi_row([
        kpi("Movies analysed", counter(len(movies)), "in the catalogue", "film", VIOLET, 0),
        kpi("Audience reviews", counter(total), "all reviews analysed", "chat", BLUE, .06),
        kpi("Positive sentiment", counter(pos_pct, "%", 1), f"{pos:,} reviews", "up", POS_COLOR, .12),
        kpi("Negative sentiment", counter(neg_pct, "%", 1), f"{neg:,} reviews", "down", NEG_COLOR, .18),
        kpi("User-submitted", counter(user_n), "via the dashboard", "user", GOLD, .24),
    ])
    md('<div style="height:1.1rem"></div>')

    eligible = stats[stats["total"] >= MIN_REVIEWS]
    ranked = eligible.sort_values(["pos_pct", "positive", "title"], ascending=[False, False, True])
    c1, c2 = st.columns([1, 1.4], gap="medium")
    with c1:
        show_chart(donut(pos, neg, "Overall sentiment distribution"))
    with c2:
        if ranked.empty:
            md(f'<div class="fp-empty">No movie has {MIN_REVIEWS}+ reviews yet.</div>')
        else:
            show_chart(pct_bar(ranked.head(6), "pos_pct", POS_COLOR, "Top movies by share of positive reviews", "Positive"))

    section("Top positively received", f"Highest share of positive reviews among movies with at least {MIN_REVIEWS} reviews.")
    if ranked.empty:
        md('<div class="fp-empty">No movie has enough reviews yet.</div>')
    else:
        for i, (col, (_, r)) in enumerate(zip(st.columns(5, gap="medium"), ranked.head(5).iterrows())):
            col.markdown(movie_card(r, compact=True, delay=i * .06), unsafe_allow_html=True)

    section("Recently submitted reviews", "Newest first. Reviews added through the dashboard are tagged NEW.")
    titles = dict(zip(movies["movie_id"], movies["title"]))
    left, right = st.columns(2, gap="medium")
    for i, (_, r) in enumerate(reviews.iloc[::-1].head(6).iterrows()):
        (left if i % 2 == 0 else right).markdown(review_card(r, titles.get(r["movie_id"], ""), i * .05), unsafe_allow_html=True)


def _select_movie(movie_id) -> None:
    st.session_state["ex_selected"] = movie_id


def _clear_movie() -> None:
    st.session_state["ex_selected"] = None


def movie_detail(row, reviews: pd.DataFrame) -> None:
    st.button("← Back to all movies", key="ex_back", on_click=_clear_movie)
    left, right = st.columns([1, 2.2], gap="large")
    with left:
        md(f'<div class="fp-card" style="max-width:300px">{poster_html(row, badge_html(row))}</div>')
    with right:
        chips = "".join(f'<span class="fp-chip">{esc(g)}</span>' for g in row["genre_list"])
        md(f'<div class="fp-pagetitle" style="font-size:2rem">{esc(row["title"])}</div>'
           f'<div class="fp-meta"><span class="fp-chip year">{esc(row["year"])}</span>{chips}</div>'
           f'<div class="fp-box-x" style="margin:.2rem 0 1.1rem;max-width:720px">{esc(row["description"])}</div>'
           f'<div class="fp-kpi-l" style="margin:0 0 .4rem">Overall audience sentiment</div>{pill(row["verdict"])}{sentiment_bar(row)}')
        if row["verdict"] == "Not Enough Reviews Yet":
            note(f"A sentiment verdict needs at least {MIN_REVIEWS} reviews.", "gold")
        kpi_row([kpi("Reviews", counter(int(row["total"])), "total", "chat", VIOLET),
                 kpi("Positive", counter(row["pos_pct"], "%", 1), f'{row["positive"]} reviews', "up", POS_COLOR),
                 kpi("Negative", counter(row["neg_pct"], "%", 1), f'{row["negative"]} reviews', "down", NEG_COLOR)])
    section("Written reviews", "Latest first, split by predicted sentiment.")
    subset = reviews[reviews["movie_id"] == row["movie_id"]].iloc[::-1]
    cp, cn = st.columns(2, gap="medium")
    for col, label in ((cp, "Positive"), (cn, "Negative")):
        part = subset[subset["sentiment"] == label]
        with col:
            md(f'<div class="fp-box-t" style="margin:.2rem 0 .7rem">{pill(label)} <span style="color:var(--muted);font-weight:500;font-size:.85rem">{len(part)} reviews</span></div>')
            if part.empty:
                md('<div class="fp-empty">No reviews in this group yet.</div>')
            else:
                md("".join(review_card(r, "", i * .04) for i, (_, r) in enumerate(part.head(8).iterrows())))
                if len(part) > 8:
                    md(f'<div class="fp-cap">Showing the latest 8 of {len(part)}.</div>')


def page_explore() -> None:
    movies, reviews, stats = CTX["movies"], CTX["reviews"], CTX["stats"]
    selected = st.session_state.get("ex_selected")
    if selected is not None and selected in set(stats["movie_id"]):
        page_header("Explore Movies", "Movie details", "Audience sentiment and written reviews for this movie.")
        movie_detail(stats[stats["movie_id"] == selected].iloc[0], reviews)
        return

    page_header("Explore Movies", "Discover how audiences feel", "Search the catalogue, filter by genre or sentiment and open any movie to read its audience reviews.")
    genres = sorted({g for lst in movies["genre_list"] for g in lst})
    c1, c2, c3, c4 = st.columns([2, 1, 1, 1], gap="medium")
    query = c1.text_input("Search by title", placeholder="Try “Dark”, “Dune”, “Coco”…", key="ex_q")
    genre = c2.selectbox("Genre", ["All genres"] + genres, key="ex_genre")
    sentiment = c3.selectbox("Sentiment", ["All sentiments", "Positive", "Negative", "Mixed", "Not enough reviews"], key="ex_sent")
    sort = c4.selectbox("Sort by", ["Title (A–Z)", "Newest first", "Most positive", "Most reviewed"], key="ex_sort")

    view = stats
    if query.strip():
        view = view[view["title"].str.contains(query.strip(), case=False, regex=False)]
    if genre != "All genres":
        view = view[view["genre_list"].apply(lambda g: genre in g)]
    if sentiment != "All sentiments":
        wanted = "Not Enough Reviews Yet" if sentiment == "Not enough reviews" else sentiment
        view = view[view["verdict"] == wanted]
    if sort == "Newest first":
        view = view.sort_values(["year", "title"], ascending=[False, True])
    elif sort == "Most positive":
        view = view.sort_values(["pos_pct", "total", "title"], ascending=[False, False, True])
    elif sort == "Most reviewed":
        view = view.sort_values(["total", "title"], ascending=[False, True])
    else:
        view = view.sort_values("title")

    md(f'<div class="fp-cap">Showing <b style="color:var(--text)">{len(view)}</b> of {len(stats)} movies</div>')
    if view.empty:
        md('<div class="fp-empty">No movies match these filters. Try a different title, genre or sentiment.</div>')
        return
    for start in range(0, len(view), 4):
        chunk = view.iloc[start:start + 4]
        for col, (i, (_, r)) in zip(st.columns(4, gap="medium"), enumerate(chunk.iterrows())):
            with col:
                st.markdown(movie_card(r, delay=i * .05), unsafe_allow_html=True)
                st.button("View details & reviews", key=f"open_{r['movie_id']}", width="stretch",
                          on_click=_select_movie, args=(int(r["movie_id"]),))


def validate_review(name: str, body: str) -> list[str]:
    errors = []
    if not name and not body:
        return ["Please enter a username and write a review."]
    if not name:
        errors.append("Please enter a username.")
    elif not re.fullmatch(r"\w[\w .'\-]{1,29}", name):
        errors.append("Username must be 2–30 characters: letters, numbers, spaces, dots, apostrophes, dashes or underscores.")
    if not body:
        errors.append("Please write your review.")
    elif len(body) < 20 or len(body.split()) < 4:
        errors.append("Your review is too short: please write at least 4 words (20 characters).")
    return errors


def page_write() -> None:
    movies, reviews, stats, valid_ids = CTX["movies"], CTX["reviews"], CTX["stats"], CTX["valid_ids"]
    page_header("Write a Review", "Add your voice", "Pick a movie and share your thoughts. The model classifies your review automatically and the dashboard updates straight away.")
    if st.session_state.pop("_wr_clear", False):
        st.session_state["wr_text"] = ""

    left, right = st.columns([1.1, 1], gap="large")
    messages: list[str] = []
    title_to_id = dict(zip(movies["title"], movies["movie_id"]))

    with left:
        title = st.selectbox("Movie", list(title_to_id), key="wr_movie")
        movie_id = int(title_to_id[title])
        with st.form("review_form", clear_on_submit=False):
            username = st.text_input("Username", max_chars=30, placeholder="e.g. Maya", key="wr_user")
            text = st.text_area("Your review", max_chars=1000, height=180, key="wr_text",
                                placeholder="What did you think? Write at least a sentence or two.")
            submitted = st.form_submit_button("Submit review", type="primary", width="stretch")
        feedback = st.container()
        md('<div class="fp-cap">Reviews are saved permanently and counted in every dashboard statistic.</div>')

    if submitted:
        name = re.sub(r"\s+", " ", username or "").strip()
        body = re.sub(r"\s+", " ", text or "").strip().lstrip("=+-@").strip()   # stops spreadsheet formula injection
        errors = validate_review(name, body)
        last = st.session_state.get("last_submission")
        if not errors and last and last["key"] == (movie_id, name.lower(), body.lower()):
            messages.append(alert("This exact review was just saved. Change the text to submit another one.", "info"))
        elif not errors:
            try:
                model, vectorizer, _ = get_model()
                with st.spinner("Analysing sentiment…"):
                    label, conf, p_pos = classify(body, model, vectorizer)
            except ValueError as exc:
                errors.append(f"Could not classify this review: {exc}. Try writing it in more detail.")
            except FileNotFoundError as exc:
                errors.append(str(exc))
            else:
                try:
                    append_review(movie_id, name, body, label, valid_ids)
                except DuplicateReview:
                    errors.append("This exact review from this username has already been submitted for this movie.")
                except StoreError as exc:
                    errors.append(f"The reviews file cannot be used: {exc}")
                except OSError as exc:
                    errors.append(f"The review could not be saved ({exc}). If the reviews CSV is open in Excel, close it and try again.")
                else:
                    st.session_state["last_submission"] = dict(
                        key=(movie_id, name.lower(), body.lower()), movie_id=movie_id, title=title,
                        username=name, label=label, conf=conf, p_pos=p_pos)
                    st.session_state["_wr_clear"] = True
                    st.rerun()
        messages += [alert(e) for e in errors]
    with feedback:
        if messages:
            md("".join(messages))

    with right:
        last = st.session_state.get("last_submission")
        if last:
            row = stats[stats["movie_id"] == last["movie_id"]].iloc[0]
            cls = VERDICT_CLASS[last["label"]]
            md(f'<div class="fp-result {cls}"><div class="fp-result-top"><div class="fp-ring" style="--pct:{last["conf"] * 100:.1f}">{last["conf"] * 100:.0f}%</div>'
               f'<div><div class="fp-result-l">PREDICTED SENTIMENT</div><div class="fp-result-v">{esc(last["label"])}'
               '<span class="fp-tick"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></span></div></div></div>'
               f'<div class="fp-result-x">Thanks, <b>{esc(last["username"])}</b>. Your review of <b>{esc(last["title"])}</b> was saved with model confidence '
               f'<b>{last["conf"] * 100:.1f}%</b>. The movie now has <b>{row["total"]}</b> reviews ({row["pos_pct"]:.0f}% positive) and its audience sentiment is <b>{esc(row["verdict"])}</b>.</div></div>')
        row = stats[stats["movie_id"] == movie_id].iloc[0]
        section("Current audience sentiment", "Updates as soon as a review is submitted.")
        p1, p2 = st.columns([1, 1.5], gap="medium")
        p1.markdown(f'<div class="fp-card">{poster_html(row)}</div>', unsafe_allow_html=True)
        p2.markdown(
            f'<div class="fp-title" style="min-height:0;font-size:1.25rem">{esc(row["title"])}</div>'
            f'<div class="fp-meta"><span class="fp-chip year">{esc(row["year"])}</span>'
            + "".join(f'<span class="fp-chip">{esc(g)}</span>' for g in row["genre_list"]) + "</div>"
            f'<div style="margin:.3rem 0">{pill(row["verdict"])}</div>{sentiment_bar(row)}'
            f'<div class="fp-cap">{row["total"]} reviews so far</div>', unsafe_allow_html=True)


def page_insights() -> None:
    movies, reviews, stats = CTX["movies"], CTX["reviews"], CTX["stats"]
    page_header("Audience Insights", "How audiences are responding", "Every chart is calculated from the current review data and updates when a new review is submitted.")
    total = len(reviews)
    if total == 0:
        md('<div class="fp-empty">There are no reviews yet, so there is nothing to analyse.</div>')
        return
    pos = int((reviews["sentiment"] == "Positive").sum())
    neg = total - pos
    user_n = int((reviews["review_type"] == "User").sum())
    words = reviews["review"].str.split().str.len()
    eligible = stats[stats["total"] >= MIN_REVIEWS]

    kpi_row([
        kpi("Total reviews", counter(total), f"{pos / total * 100:.1f}% positive", "chat", VIOLET, 0),
        kpi("User-submitted", counter(user_n), "via the dashboard", "user", GOLD, .06),
        kpi("Unique reviewers", counter(reviews["username"].str.lower().nunique()), "distinct usernames", "layers", BLUE, .12),
        kpi("Avg reviews / movie", counter(total / len(movies), "", 1), f"across {len(movies)} movies", "film", CRIMSON, .18),
        kpi("Avg review length", counter(float(words.mean()), "", 1), "words per review", "ruler", VIOLET, .24),
    ])
    md('<div style="height:1.1rem"></div>')

    section("Overall sentiment", "Positive versus negative reviews, and how every movie splits.")
    c1, c2 = st.columns([1, 1.5], gap="medium")
    with c1:
        show_chart(donut(pos, neg, "Positive vs negative"))
    with c2:
        show_chart(stacked_by_movie(stats))

    section("Best and worst received", f"Ranked by share of positive or negative reviews. Only movies with {MIN_REVIEWS}+ reviews are ranked.")
    c3, c4 = st.columns(2, gap="medium")
    with c3:
        top = eligible.sort_values(["pos_pct", "positive", "title"], ascending=[False, False, True]).head(5)
        if not top.empty:
            show_chart(pct_bar(top, "pos_pct", POS_COLOR, "Most positively received", "Positive"))
    with c4:
        bottom = eligible.sort_values(["neg_pct", "negative", "title"], ascending=[False, False, True]).head(5)
        if not bottom.empty:
            show_chart(pct_bar(bottom, "neg_pct", NEG_COLOR, "Most negative audience reception", "Negative"))
    negative_movies = int((stats["verdict"] == "Negative").sum())
    md(f'<div class="fp-cap"><b style="color:var(--text)">{negative_movies}</b> of {len(stats)} movies currently have a Negative audience verdict (more than half of their reviews are negative).</div>')

    section("Review distribution", "Where the reviews are, by movie and by genre.")
    c5, c6 = st.columns([1.4, 1], gap="medium")
    with c5:
        per = stats.sort_values(["total", "title"], ascending=[True, False])
        show_chart(stacked_counts(per, "title", "Reviews per movie", max(420, 26 * len(per) + 90), horizontal=True))
    with c6:
        exploded = reviews.merge(movies[["movie_id", "genre_list"]], on="movie_id").explode("genre_list")
        g = exploded.groupby(["genre_list", "sentiment"]).size().unstack(fill_value=0)
        for s in SENTIMENTS:
            if s not in g.columns:
                g[s] = 0
        g = g.rename(columns={"Positive": "positive", "Negative": "negative"})
        g["total"] = g["positive"] + g["negative"]
        g = g.sort_values("total", ascending=True).reset_index().rename(columns={"genre_list": "genre"})
        show_chart(stacked_counts(g, "genre", "Reviews by genre", max(420, 26 * len(g) + 90), horizontal=True))
        md('<div class="fp-cap">A review counts toward every genre listed for its movie, so genre totals exceed the number of reviews.</div>')

    section("Review activity", "Who is reviewing and where the reviews come from.")
    c7, c8 = st.columns([1, 1.4], gap="medium")
    with c7:
        most = stats.sort_values(["total", "title"], ascending=[False, True]).iloc[0]
        least = stats.sort_values(["total", "title"], ascending=[True, True]).iloc[0]
        src = reviews["review_type"].value_counts()
        with card():
            md('<div class="fp-box-t">Activity summary</div>')
            md(html_table(pd.DataFrame([
                ("Sample reviews", f"{int(src.get('Sample', 0)):,}"),
                ("User-submitted reviews", f"{user_n:,}"),
                ("Most reviewed movie", f"{most['title']} ({int(most['total'])})"),
                ("Least reviewed movie", f"{least['title']} ({int(least['total'])})"),
                ("Longest review", f"{int(words.max())} words"),
                ("Shortest review", f"{int(words.min())} words")], columns=["Metric", "Value"])))
    with c8:
        who = reviews.assign(u=reviews["username"].str.title()).groupby("u").agg(
            Reviews=("review", "size"), Positive=("sentiment", lambda s: int((s == "Positive").sum()))).reset_index()
        who["Positive share"] = (who["Positive"] / who["Reviews"] * 100).round(0).astype(int).astype(str) + "%"
        who = who.sort_values(["Reviews", "u"], ascending=[False, True]).head(8).rename(columns={"u": "Reviewer"})
        with card():
            md('<div class="fp-box-t">Most active reviewers</div>')
            md(html_table(who[["Reviewer", "Reviews", "Positive", "Positive share"]]))
    timed = reviews.dropna(subset=["submitted_at"])
    if not timed.empty:
        daily = timed.assign(day=timed["submitted_at"].dt.strftime("%Y-%m-%d")).groupby(["day", "sentiment"]).size().unstack(fill_value=0)
        for s in SENTIMENTS:
            if s not in daily.columns:
                daily[s] = 0
        daily = daily.rename(columns={"Positive": "positive", "Negative": "negative"}).reset_index()
        show_chart(stacked_counts(daily, "day", "Dashboard submissions per day (UTC)", 300))
    note("Sentiment describes the wording of audience reviews. It is not an objective measurement of movie quality.")


def page_model() -> None:
    page_header("Model Performance", "How the classifier performed", "Results of the trained Multinomial Naive Bayes model on the held-out IMDb test reviews.")
    try:
        model, vectorizer, notes = get_model()
    except Exception as exc:  # noqa: BLE001 - shown to the user, with the cause
        md(alert(f"The model could not be loaded: {exc}"))
        return
    note("<b>These are the model's recorded test results on the IMDb review dataset.</b> They are separate from the audience statistics elsewhere in FilmPulse, "
         "which describe the demo reviews and any new submissions. The numbers below are shown as originally evaluated; the model has not been retrained or re-scored.")

    tn, fp, fn, tp = (int(v) for v in CONFUSION.ravel())
    n = tn + fp + fn + tp
    accuracy = (tn + tp) / n * 100
    prec = {"Negative": tn / (tn + fn), "Positive": tp / (tp + fp)}
    rec = {"Negative": tn / (tn + fp), "Positive": tp / (tp + fn)}
    f1 = {k: 2 * prec[k] * rec[k] / (prec[k] + rec[k]) for k in prec}
    macro = lambda d: float(np.mean(list(d.values())))  # noqa: E731

    kpi_row([
        kpi("Accuracy", counter(accuracy, "%", 2), f"{tn + tp:,} of {n:,} test reviews correct", "target", GOLD, 0),
        kpi("Precision (macro)", counter(macro(prec) * 100, "%", 1), "of predicted labels that were right", "up", BLUE, .06),
        kpi("Recall (macro)", counter(macro(rec) * 100, "%", 1), "of true labels that were found", "layers", VIOLET, .12),
        kpi("F1-score (macro)", counter(macro(f1) * 100, "%", 1), "balance of precision and recall", "ruler", CRIMSON, .18),
    ])

    section("Evaluation results", f"{n:,} test reviews, {int(CONFUSION[0].sum()):,} per class.")
    c1, c2 = st.columns([1, 1.1], gap="medium")
    with c1:
        pct = CONFUSION / CONFUSION.sum(axis=1, keepdims=True) * 100
        text = [[f"<b>{CONFUSION[i, j]:,}</b><br>{pct[i, j]:.1f}% of actual" for j in range(2)] for i in range(2)]
        fig = go.Figure(go.Heatmap(
            z=CONFUSION, x=["Predicted Negative", "Predicted Positive"], y=["Actual Negative", "Actual Positive"],
            text=text, texttemplate="%{text}", textfont=dict(size=14, color="#fff", family=FONT),
            colorscale=[[0, "#1b1e2e"], [.5, "#4b2a6e"], [1, VIOLET]], showscale=False, xgap=5, ygap=5,
            hovertemplate="%{y}, %{x}: %{z:,} reviews<extra></extra>"))
        style_fig(fig, "Confusion matrix", 390).update_yaxes(autorange="reversed")
        show_chart(fig)
    with c2:
        classes = ["Negative", "Positive"]
        fig = go.Figure()
        for name, vals, color in (("Precision", prec, BLUE), ("Recall", rec, VIOLET), ("F1-score", f1, GOLD)):
            fig.add_trace(go.Bar(name=name, x=classes, y=[vals[c] for c in classes], marker=dict(color=color),
                                 text=[f"{vals[c]:.2f}" for c in classes], textposition="outside", textfont=dict(color=TEXT),
                                 hovertemplate="%{x} " + name + ": %{y:.4f}<extra></extra>"))
        style_fig(fig, "Precision, recall and F1 per class", 390).update_layout(barmode="group", bargap=.3)
        fig.update_yaxes(range=[0, 1.05])
        show_chart(fig)

    report = pd.DataFrame({
        "Class": ["Negative", "Positive", "Accuracy", "Macro average", "Weighted average"],
        "Precision": [f"{prec['Negative']:.2f}", f"{prec['Positive']:.2f}", "", f"{macro(prec):.2f}", f"{macro(prec):.2f}"],
        "Recall": [f"{rec['Negative']:.2f}", f"{rec['Positive']:.2f}", "", f"{macro(rec):.2f}", f"{macro(rec):.2f}"],
        "F1-score": [f"{f1['Negative']:.2f}", f"{f1['Positive']:.2f}", f"{(tn + tp) / n:.2f}", f"{macro(f1):.2f}", f"{macro(f1):.2f}"],
        "Support": [f"{int(CONFUSION[0].sum()):,}", f"{int(CONFUSION[1].sum()):,}", f"{n:,}", f"{n:,}", f"{n:,}"]})
    params = vectorizer.get_params()
    config = [("Algorithm", "Multinomial Naive Bayes"), ("Smoothing (alpha)", getattr(model, "alpha", "n/a")),
              ("Feature extraction", "TF-IDF (TfidfVectorizer)"), ("max_features", params.get("max_features")),
              ("ngram_range", str(params.get("ngram_range"))), ("min_df", params.get("min_df")),
              ("sublinear_tf", params.get("sublinear_tf")), ("Vocabulary size", f"{len(vectorizer.vocabulary_):,} terms"),
              ("Classes", ", ".join(f"{c} = {to_label(c)}" for c in model.classes_))]
    c3, c4 = st.columns([1.15, 1], gap="medium")
    with c3:
        with card():
            md('<div class="fp-box-t">Classification report</div>')
            md(html_table(report, sep_rows=(2,)))
            md(f'<div class="fp-cap">Accuracy {accuracy:.2f}%. Derived from the confusion matrix of the original test evaluation.</div>')
    with c4:
        with card():
            md('<div class="fp-box-t">Model configuration</div>')
            md(html_table(pd.DataFrame(config, columns=["Setting", "Value"])))
            md('<div class="fp-cap">Read directly from the loaded model.</div>')
    seen = set()
    for text in notes:
        m = re.search(r"from version (\S+) when using version (\S+)", text)
        msg = (f"The model file was saved with scikit-learn {m.group(1)} but {m.group(2)} is installed. It loads and predicts normally; "
               f"install scikit-learn=={m.group(1)} to remove the warning." if m else f"Model loading note: {text}")
        if msg not in seen:
            seen.add(msg)
            md(alert(msg, "warn" if m else "info"))

    section("How it works", "The three ideas behind the classifier.")
    a, b, c = st.columns(3, gap="medium")
    a.markdown(box("The model", "A <b>Multinomial Naive Bayes</b> classifier turns the TF-IDF weights of a review into one of two labels: Positive or Negative. "
                   "It was trained once on 25,000 labelled IMDb reviews and is loaded as-is. FilmPulse never retrains it.", "🧠"), unsafe_allow_html=True)
    b.markdown(box("TF-IDF features", "Each review becomes a vector over a 50,000-term vocabulary of words and word pairs (n-grams 1–2, min_df 2). "
                   "<b>TF</b> counts how often a term appears (sublinear: 1 + log tf); <b>IDF</b> down-weights terms that appear in many reviews."
                   '<span class="fp-formula">tfidf(t, d) = (1 + ln tf) × ln((1 + N) / (1 + df)) + 1</span>', "🔤", .05), unsafe_allow_html=True)
    c.markdown(box("Naive Bayes", "Bayes' rule combines how common each class is with how likely each term is within it, assuming terms are independent (the “naive” part)."
                   '<span class="fp-formula">ŷ = argmax<sub>c</sub> [ log P(c) + Σ<sub>t</sub> x<sub>t</sub> · log P(t | c) ]</span>'
                   "Fast, needs little data and works well for text.", "📐", .1), unsafe_allow_html=True)

    section("What the model learned", "Terms with the strongest pull toward each class, taken from the loaded model's word probabilities.")
    try:
        pos_terms, neg_terms = model_top_terms(model, vectorizer)
    except (AttributeError, ValueError) as exc:
        md(alert(f"Top terms are unavailable for this model: {exc}", "info"))
        return
    c5, c6 = st.columns(2, gap="medium")
    for col, terms, color, title in ((c5, pos_terms, POS_COLOR, "Signals of Positive"), (c6, neg_terms, NEG_COLOR, "Signals of Negative")):
        t = terms[::-1]
        fig = go.Figure(go.Bar(x=[v for _, v in t], y=[w for w, _ in t], orientation="h", marker=dict(color=color),
                               hovertemplate="“%{y}”: log-odds %{x:.2f}<extra></extra>"))
        style_fig(fig, title, 380).update_xaxes(title=dict(text="Log-probability difference between classes", font=dict(size=11, color=MUTED)))
        with col:
            show_chart(fig)


def page_about() -> None:
    movies, reviews = CTX["movies"], CTX["reviews"]
    page_header("About FilmPulse", "Turning opinions into insight", "An academic project: Movie Review Sentiment Detection using Naive Bayes.")
    sample_n = int((reviews["review_type"] == "Sample").sum())

    a, b = st.columns(2, gap="medium")
    a.markdown(box("What FilmPulse does", "FilmPulse is a movie-review analytics dashboard. People write reviews; a machine-learning model reads each one, decides whether it is "
                   "<b>Positive</b> or <b>Negative</b>, and the dashboard turns those predictions into live statistics for every movie, genre and for the audience as a whole.", "🎬"), unsafe_allow_html=True)
    b.markdown(box("The problem it addresses", "Reading hundreds of reviews to judge how a movie is received is slow and subjective. Automatic sentiment detection turns free text into "
                   "measurable signals that can be summarised, compared and tracked as new opinions arrive.", "🎯", .05), unsafe_allow_html=True)
    md('<div style="height:.9rem"></div>')

    section("How sentiment analysis works", "From raw text to a prediction in four steps.")
    md('<div class="fp-flow"><div><b>1 · Text</b>A user writes a review in plain English.</div>'
       '<div><b>2 · Tokenise</b>Lower-case words and word pairs (unigrams + bigrams) are extracted.</div>'
       '<div><b>3 · TF-IDF</b>Each term is weighted by how informative it is, giving a 50,000-value vector.</div>'
       '<div><b>4 · Naive Bayes</b>Class probabilities are compared; the higher one is the sentiment.</div></div>')
    md('<div style="height:.9rem"></div>')

    a, b = st.columns(2, gap="medium")
    a.markdown(box("Machine-learning model",
                   "<ul><li><b>Features:</b> TF-IDF, unigrams and bigrams, max 50,000 features, min_df 2, sublinear term frequency.</li>"
                   "<li><b>Classifier:</b> Multinomial Naive Bayes, alpha 0.5.</li>"
                   "<li><b>Training and testing data:</b> IMDb movie reviews, 25,000 test reviews.</li>"
                   "<li><b>Result:</b> 87.24% accuracy. See <i>Model Performance</i> for the full evaluation.</li>"
                   "<li>The saved model is loaded as-is and never retrained.</li></ul>", "🧠"), unsafe_allow_html=True)
    b.markdown(
        '<div class="fp-box"><div class="fp-box-t"><i>🛠</i>Technologies used</div><div class="fp-tech">'
        '<span>Python</span><span>Streamlit</span><span>scikit-learn</span><span>Pandas</span><span>NumPy</span><span>Plotly</span><span>TF-IDF</span><span>Naive Bayes</span></div>'
        '<div class="fp-box-x" style="margin-top:1rem">Everything runs locally. No database, API key or separate backend is needed. Reviews are stored in a CSV file.</div></div>',
        unsafe_allow_html=True)
    md('<div style="height:.9rem"></div>')

    section("Project workflow")
    steps = [("Choose a movie", "and write a review with a username."),
             ("Validate the input", "so empty, very short or duplicate reviews are rejected."),
             ("Vectorize the text", "with the existing fitted TF-IDF vectorizer."),
             ("Predict sentiment", "with the saved Naive Bayes model."),
             ("Save the review", "to a CSV file so it persists after a restart."),
             ("Refresh the dashboard", "so every metric and chart reflects the new review.")]
    md('<div class="fp-box">' + "".join(
        f'<div class="fp-step"><div class="fp-step-n">{i}</div><div class="fp-step-t"><b>{esc(t)}</b> {esc(d)}</div></div>'
        for i, (t, d) in enumerate(steps, 1)) + "</div>")

    section("Practical applications")
    a, b, c = st.columns(3, gap="medium")
    a.markdown(box("Studios and distributors", "Track audience reaction to trailers and releases, and spot problems early.", "🎞", 0), unsafe_allow_html=True)
    b.markdown(box("Streaming platforms", "Summarise thousands of user reviews into a single sentiment signal per title.", "📺", .05), unsafe_allow_html=True)
    c.markdown(box("Brands and customer care", "The same technique classifies product reviews, support tickets and social-media posts.", "💬", .1), unsafe_allow_html=True)

    section("Data and sentiment rule")
    a, b = st.columns(2, gap="medium")
    a.markdown(box("Datasets",
                   "<ul><li><b>Model training and testing:</b> the IMDb movie review dataset. These reviews do not belong to the movies shown in FilmPulse.</li>"
                   f"<li><b>Demonstration data:</b> {len(movies)} movies and {sample_n} sample audience reviews, plus reviews submitted through the dashboard.</li></ul>"), unsafe_allow_html=True)
    b.markdown(box("How a movie's overall sentiment is decided",
                   f"<ul><li>Fewer than {MIN_REVIEWS} reviews: <b>Not Enough Reviews Yet</b>.</li><li>More than 50% positive: <b>Positive</b>.</li>"
                   "<li>Less than 50% positive: <b>Negative</b>.</li><li>Exactly 50%: <b>Mixed</b>.</li></ul>"), unsafe_allow_html=True)

    section("Limitations")
    md(box("Good to know", "<ul><li>The model was trained on long IMDb reviews, so very short or unusual text can be misclassified.</li>"
           "<li>Naive Bayes ignores word order and context, so sarcasm, negation and mixed opinions can be missed.</li>"
           "<li>It predicts only Positive or Negative, with no neutral class.</li>"
           "<li>Audience sentiment is model-predicted, so model errors carry into the statistics.</li>"
           "<li>The sample reviews are short and repeated across movies, so their statistics are illustrative, not real audience data.</li>"
           "<li>Sentiment reflects review wording, not the objective quality of a movie.</li></ul>"))


