def warm_up_widgets() -> None:
    """Render one of each lazily-loaded input widget, invisibly, on the first run of a session.

    Streamlit fetches widget code (TextInput, TextArea, Selectbox, Button) on demand the first time a widget
    of that type appears. Fetching them up-front, while the connection is idle, makes the later Explore and
    Write pages independent of a second burst of requests that flaky tunnels (e.g. LocalTunnel) can drop.
    """
    if st.session_state.get("_fp_warm"):
        return
    st.session_state["_fp_warm"] = True
    with st.container(key="fp_warm"):
        st.text_input("warm-up", key="_warm_ti", label_visibility="collapsed")
        st.text_area("warm-up", key="_warm_ta", label_visibility="collapsed")
        st.selectbox("warm-up", ["-"], key="_warm_sb", label_visibility="collapsed")
        st.button("warm-up", key="_warm_btn")


def render_sidebar_footer() -> None:
    with st.sidebar:
        movies, reviews = CTX["movies"], CTX["reviews"]
        md(f'<div class="fp-sidefoot"><span class="dot"></span><b>{len(movies)}</b> movies · <b>{len(reviews):,}</b> reviews<br>'
           'TF-IDF + Multinomial Naive Bayes</div>')


def main() -> None:
    global _card_ids, CTX
    _card_ids = iter(range(10_000))
    md(CSS)
    warm_up_widgets()
    try:
        st.logo(LOGO_URI, size="large")
    except Exception:  # noqa: BLE001 - the logo is cosmetic; very old Streamlit versions lack some arguments
        pass

    pages = [
        st.Page(page_home, title="Home", icon=":material/home:", url_path="home", default=True),
        st.Page(page_explore, title="Explore Movies", icon=":material/movie:", url_path="explore"),
        st.Page(page_write, title="Write a Review", icon=":material/edit_note:", url_path="write"),
        st.Page(page_insights, title="Audience Insights", icon=":material/monitoring:", url_path="insights"),
        st.Page(page_model, title="Model Performance", icon=":material/psychology:", url_path="model"),
        st.Page(page_about, title="About FilmPulse", icon=":material/info:", url_path="about"),
    ]
    current = st.navigation(pages, position="sidebar")

    try:
        CTX = build_context()
    except (FileNotFoundError, ValueError, StoreError, OSError) as exc:
        md(alert(f"FilmPulse could not load its data: {exc}"))
        md(f'<div class="fp-alert info">Place filmpulse_model.joblib, filmpulse_movies.csv and filmpulse_reviews.csv in the same folder as filmpulse.py: {esc(BASE_DIR)}</div>')
        st.stop()
    if CTX["movies"].empty:
        md(alert("The movie catalogue is empty. Add movies to filmpulse_movies.csv."))
        st.stop()

    if current.title != "Write a Review":
        st.session_state.pop("last_submission", None)
    if current.title != "Explore Movies":
        st.session_state["ex_selected"] = None
    render_sidebar_footer()
    if CTX["dropped"]:
        md(alert(f"{CTX['dropped']} row(s) in the reviews data were ignored because they were invalid (unknown movie, empty text or unrecognised sentiment).", "warn"))
    current.run()


